!function(){"use strict";app.directive("btnDataAdicionalArticulo",(function(modalService,nombreModal){return{restrict:"A",scope:{entity:"=",getDataEtiqueta:"&",datosAdicionales:"="},link:function(scope,element,attrs){element.on("click",(async function(){if(console.log(scope),!Number.isInteger(scope.entity.cantidad))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"El valor de la cantidad del artículo tiene que ser un número entero!"});let{ModalDatoAdicionalArticuloCtrl:ModalDatoAdicionalArticuloCtrl}=await import("/js/compras/modals/modalDatoAdicionalArticulo.js"+CHANGE_VERSION()),modalRef;modalService.openModalCustom({controller:ModalDatoAdicionalArticuloCtrl,template:"~/Areas/Compra/Pages/Shared/_ModalDatoAdicionalArticulo.cshtml",size:"lg",params:{entity:scope.entity,datosAdicionales:scope.datosAdicionales},isRenderRazorPartial:!0}).result.then((function(result){if("object"==typeof result)if(scope.datosAdicionales.some(item=>item.idArticulo===scope.entity.idArticulo))for(let label of scope.datosAdicionales)label.idArticulo===scope.entity.idArticulo&&(label.adicionales=result.data);else scope.datosAdicionales.push({idArticulo:scope.entity.idArticulo,idEtiqueta:scope.entity.etiquetas[0].idEtiqueta,adicionales:result.data});console.log(scope.datosAdicionales)}))}))}}}))}(window.angular);